list_aliases.code:
var response = await client.Aliases.ListAliasesAsync(
    new Dictionary<string, object?> { ["limit"] = 20 });
var body = (IReadOnlyDictionary<string, object?>)response.Map!;
foreach (var domainAlias in ((IReadOnlyList<object?>)body["aliases"]!).Cast<IReadOnlyDictionary<string, object?>>())
    Console.WriteLine($"{domainAlias["id"]} {domainAlias["alias"]}");

create_alias.code:
var response = await client.Aliases.CreateAliasAsync(new Dictionary<string, object?>
{
    ["alias"] = "shop.example.com",
});
var body = (IReadOnlyDictionary<string, object?>)response.Map!;
var domainAlias = (IReadOnlyDictionary<string, object?>)body["alias"]!;
Console.WriteLine($"{domainAlias["id"]} {domainAlias["alias"]}");
